<script setup lang="ts">
import { computed,reactive,ref } from 'vue'
import { X,Check,LoaderCircle,Plus } from 'lucide-vue-next'
import FormFields from './FormFields.vue'
import ProductEditor from './ProductEditor.vue'
import { saveRow,state } from '../api'
import type { Row } from '../types'
import { localNow,shanghaiDate,collectionLabels } from '../types'
const props=defineProps<{collection:string;row?:Row;preset?:Record<string,any>}>();const emit=defineEmits<{close:[];saved:[row:Row,collection:string]}>()
const schema=computed(()=>state.schema.find(s=>s.name===props.collection))
const defaults:Record<string,any>={kind:'SMOKING',currency:'CNY',priceType:'PERSONAL',effectiveDate:shanghaiDate(),sourceDate:shanghaiDate(),occurredAt:localNow(),startedAt:localNow(),measuredAt:localNow(),date:shanghaiDate(),source:'SELF',payer:'SELF',timePrecision:'EXACT',count:1,unitCount:20,quantity:1,inputMode:'BOTTLES',bottles:1,share:1,manualAlcohol:'AUTO',sex:'UNSPECIFIED',period:'WEEK',enabled:true,active:true,verified:false,favorite:false,locked:false,complete:true}
const form=reactive<Record<string,any>>(props.row?{...props.row}:{...Object.fromEntries((schema.value?.fields||[]).map(f=>[f.key,defaults[f.key]??(f.type==='boolean'?false:'')])),...props.preset})
const createId=crypto.randomUUID();const saving=ref(false),error=ref('')
const productInline=ref(false)
function inlineProductSaved(row:Row){state.collections.products=[row,...(state.collections.products||[]).filter(p=>p.id!==row.id)];form.productId=row.id;if(props.collection==='drinks'){form.bottleMl=row.bottleMl;form.abv=row.abv}productInline.value=false}
async function submit(){saving.value=true;error.value='';try{const fields=Object.fromEntries((schema.value?.fields||[]).map(f=>[f.key,form[f.key]===''?null:form[f.key]]));if(!props.row)fields.id=createId;const r=await saveRow(props.collection,fields,props.row);emit('saved',r,props.collection)}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
</script>
<template><ProductEditor v-if="collection==='products'" :row="row" :preset="preset" @close="emit('close')" @saved="(r,c)=>emit('saved',r,c)"/><div v-else v-show="!productInline" class="overlay" @click.self="emit('close')"><section class="drawer" role="dialog" aria-modal="true" :aria-label="(row?'编辑':'新增')+(schema?.label||collectionLabels[collection])"><header class="drawer-header"><div><small>DATA EDITOR</small><h2>{{row?'编辑':'新增'}}{{schema?.label||collectionLabels[collection]}}</h2></div><button class="icon-button" title="关闭" @click="emit('close')"><X :size="20"/></button></header><form class="drawer-form" @submit.prevent="submit"><div class="drawer-body"><p class="muted small">按实际情况填写。已有费用保留原单价；补齐种类单价后，缺失费用会在资料足够时自动补全。</p><p v-if="collection==='prices'" class="hint">这里保存价格历史与参考资料，不会替换商品当前采用的单价。请在“商品资料 → 设置单价”中设置并确认现行计价。</p><FormFields v-if="schema" :fields="schema.fields" :model="form" :collection="collection" :require-product="!row&&['smoking','drinks'].includes(collection)"/><p v-else class="error-box">未取得这个数据表的字段定义，请刷新后重试。</p><button v-if="['smoking','drinks'].includes(collection)" type="button" class="button secondary" @click="productInline=true"><Plus :size="16"/>没有想要的种类？在这里新增</button><div v-if="row" class="meta-box">记录编号 {{row.id}}<br/>版本 {{row.version}} · 更新于 {{String(row.updatedAt||'').replace('T',' ')}}</div><p v-if="error" class="error-box" role="alert">{{error}}</p></div><footer class="drawer-footer"><button type="button" class="button secondary" @click="emit('close')">取消</button><button class="button primary" :disabled="saving||!schema"><LoaderCircle v-if="saving" class="spin" :size="17"/><Check v-else :size="17"/>{{saving?'正在保存':'保存记录'}}</button></footer></form></section></div><ProductEditor v-if="productInline" :kind="collection==='smoking'?'SMOKING':'ALCOHOL'" @close="productInline=false" @saved="inlineProductSaved"/></template>
